mapper.select:
select count(*)
from chat_message M
where M.chat_channel_no = #{channelNo}



        and M.chat_message_no < #{lastMessageNo}

mapper.update:
update chat_message
set chat_message_deleted = 'Y'
where chat_message_no = #{chatMessageNo}

mapper.insert:
insert into chat_read (
	chat_message_no,
	project_member_no
)
select 
	M.chat_message_no,
	#{projectMemberNo}
from chat_message M
where M.chat_channel_no = #{channelNo}
	and not exists (
		select 1
		from chat_read CR
		where CR.chat_message_no = M.chat_message_no
			and CR.project_member_no = #{projectMemberNo}
	)

mapper.select:
select count(*)
from project_member PM
join chat_channel CC
	on PM.project_no = CC.project_no
where CC.chat_channel_no = #{channelNo}
	and PM.project_member_no != #{projectMemberNo}
	and not exists (
		select 1
		from chat_read CR
		where CR.chat_message_no = #{chatMessageNo}
			and CR.project_member_no = PM.project_member_no
	)
